function is2xx(status) {
	return status >= 200 && status <= 299;
}

function stripFragment(url) {
	const i = url.indexOf("#");
	return i === -1 ? url : url.slice(0, i);
}

function deepCopy(value) {
	if (value === null || typeof value !== "object") return value;
	if (Array.isArray(value)) return value.map(deepCopy);
	if (value instanceof Date) return new Date(value.getTime());
	if (value instanceof RegExp) return new RegExp(value.source, value.flags);
	if (value instanceof Map) {
		const out = new Map();
		for (const [k, v] of value) out.set(deepCopy(k), deepCopy(v));
		return out;
	}
	if (value instanceof Set) return new Set([...value].map(deepCopy));
	const out = {};
	for (const [k, v] of Object.entries(value)) out[k] = deepCopy(v);
	return out;
}

export function createClient({ fetchImpl, now = Date.now, ttlMs } = {}) {
	if (typeof fetchImpl !== "function") throw new TypeError("fetchImpl must be a function");
	if (ttlMs !== undefined && (!Number.isInteger(ttlMs) || ttlMs < 0)) {
		throw new RangeError("ttlMs must be an integer of 0 or more");
	}
	const ttl = ttlMs === undefined ? 0 : ttlMs;

	const cache = new Map(); // key -> { value, stamp }
	const inflight = new Map(); // key -> promise of normalized { status, body }
	const counters = { hits: 0, misses: 0, fetches: 0 };

	async function runFetch(key) {
		counters.fetches += 1;
		const pending = (async () => {
			const response = await fetchImpl(key);
			return { status: response.status, body: response.body };
		})();
		inflight.set(key, pending);
		try {
			const response = await pending;
			const stamp = now();
			if (ttl > 0 && is2xx(response.status)) {
				cache.set(key, { value: deepCopy(response), stamp });
			}
			return deepCopy(response);
		} finally {
			if (inflight.get(key) === pending) inflight.delete(key);
		}
	}

	return {
		async get(url, options) {
			if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
			const key = stripFragment(url);
			const fresh = options?.fresh === true;

			if (!fresh && ttl > 0) {
				const entry = cache.get(key);
				if (entry !== undefined) {
					if (now() - entry.stamp < ttl) {
						counters.hits += 1;
						return deepCopy(entry.value);
					}
					cache.delete(key);
				}
			}

			counters.misses += 1;
			if (!fresh) {
				const pending = inflight.get(key);
				if (pending !== undefined) {
					return deepCopy(await pending);
				}
			}
			return runFetch(key);
		},
		clear(url) {
			if (arguments.length === 0) {
				cache.clear();
				return;
			}
			if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
			cache.delete(stripFragment(url));
		},
		stats() {
			return { hits: counters.hits, misses: counters.misses, fetches: counters.fetches };
		},
	};
}

import assert from "node:assert/strict";
import { createClient } from "./src/client.js";

const tick = () => new Promise((r) => setTimeout(r, 0));

// R1: ttlMs validation
assert.throws(() => createClient({ fetchImpl: async () => {}, ttlMs: null }), RangeError);
assert.throws(() => createClient({ fetchImpl: async () => {}, ttlMs: "5" }), RangeError);
assert.throws(() => createClient({ fetchImpl: async () => {}, ttlMs: NaN }), RangeError);
assert.throws(() => createClient({ fetchImpl: async () => {}, ttlMs: -1 }), RangeError);
assert.throws(() => createClient({ fetchImpl: async () => {}, ttlMs: 1.5 }), RangeError);
assert.doesNotThrow(() => createClient({ fetchImpl: async () => {}, ttlMs: 0 }));
assert.doesNotThrow(() => createClient({ fetchImpl: async () => {} }));

// R2: basic cache + fragment + expiry boundary
{
	let t = 0;
	let calls = 0;
	const client = createClient({
		ttlMs: 100,
		now: () => t,
		fetchImpl: async (url) => { calls++; assert.ok(!url.includes("#")); return { status: 200, body: { url, n: calls } }; },
	});
	const a = await client.get("http://x/a#frag1");
	assert.equal(calls, 1);
	assert.deepEqual(a, { status: 200, body: { url: "http://x/a", n: 1 } });
	const b = await client.get("http://x/a#frag2"); // same URL, different fragment
	assert.equal(calls, 1);
	assert.deepEqual(b, { status: 200, body: { url: "http://x/a", n: 1 } });
	t = 99;
	await client.get("http://x/a"); // 99 - 0 < 100 -> hit
	assert.equal(calls, 1);
	t = 100;
	const c = await client.get("http://x/a"); // 100 - 0 >= 100 -> expired, refetch
	assert.equal(calls, 2);
	assert.equal(c.body.n, 2);
	// stamp read right after fetch resolved: now() was 100 at resolve
	t = 199;
	await client.get("http://x/a"); // 199 - 100 = 99 < 100 -> hit (proves stamp post-resolve)
	assert.equal(calls, 2);
	t = 200;
	await client.get("http://x/a"); // expired again
	assert.equal(calls, 3);
	assert.deepEqual(client.stats(), { hits: 3, misses: 3, fetches: 3 });
}

// R1: ttlMs 0 never stores
{
	let calls = 0;
	const client = createClient({ fetchImpl: async () => { calls++; return { status: 200, body: 1 }; } });
	await client.get("http://x/a");
	await client.get("http://x/a");
	assert.equal(calls, 2);
	assert.deepEqual(client.stats(), { hits: 0, misses: 2, fetches: 2 });
}

// R3: non-2xx returned but not stored; rejection propagates, nothing stored
{
	let calls = 0;
	let t = 0;
	const client = createClient({
		ttlMs: 100, now: () => t,
		fetchImpl: async (u) => { calls++; return calls === 1 ? { status: 404, body: "nf" } : { status: 200, body: "ok" }; },
	});
	const r = await client.get("http://x/e");
	assert.deepEqual(r, { status: 404, body: "nf" });
	await client.get("http://x/e"); // not cached -> refetch
	assert.equal(calls, 2);
	t = 50;
	let boomed = false;
	const client2 = createClient({
		ttlMs: 100, now: () => t,
		fetchImpl: async () => { throw new Error("boom"); },
	});
	await assert.rejects(() => client2.get("http://x/f"), /boom/);
	await client2.get("http://x/f"); // nothing stored on rejection -> refetch
	assert.equal(client2.stats().fetches, 2);
	assert.equal(client2.stats().hits, 0);
}

// R4: in-flight coalescing (same result AND same rejection shared), works with ttl 0 too
{
	let release;
	const resolvers = [];
	let calls = 0;
	const client = createClient({
		fetchImpl: () => { calls++; return new Promise((res) => resolvers.push(() => res({ status: 200, body: { calls } }))); },
	});
	const p1 = client.get("http://x/g#1");
	const p2 = client.get("http://x/g#2");
	const p3 = client.get("http://x/g");
	resolvers[0]();
	const [r1, r2, r3] = await Promise.all([p1, p2, p3]);
	assert.equal(calls, 1);
	assert.deepEqual(r1.body, { calls: 1 });
	assert.equal(r1, r2, false); // distinct copies
	r1.body.calls = 999;
	assert.equal(r2.body.calls, 1);
	assert.deepEqual(client.stats(), { hits: 0, misses: 3, fetches: 1 });
