	const client3 = createClient({ fetchImpl: () => new Promise((_, rej) => { release2 = () => rej(new Error("nope")); }) });
	const q1 = client3.get("http://x/h");
	const q2 = client3.get("http://x/h#z");
	release2();
	await assert.rejects(() => q1, /nope/);
	await assert.rejects(() => q2, /nope/);
	assert.deepEqual(client3.stats(), { hits: 0, misses: 2, fetches: 1 });
	// next call starts afresh (in-flight cleaned up)
	await client3.get("http://x/h").catch(() => {});
	assert.equal(client3.stats().fetches, 2);
