	t2 = 500;
	await clientB.get("http://x/m", { fresh: true }); // calls2=3, 200 -> stored stamp 500
	t2 = 999; // 999-500=499 < 1000 -> hit
	const hit = await clientB.get("http://x/m");
	assert.equal(clientB.stats().hits, 1);
	assert.deepEqual(hit.body, { calls2: 3 });
