{
	let calls = 0;
	let t = 0;
	const client = createClient({ ttlMs: 1000, now: () => t, fetchImpl: async () => { calls++; return { status: 200, body: calls }; } });
	await client.get("http://x/a");
	await client.get("http://x/b");
	assert.equal(calls, 2);
	client.clear("http://x/a#frag");
	await client.get("http://x/a"); // refetch
	await client.get("http://x/b"); // still cached
	assert.equal(calls, 3);
	assert.equal(client.stats().hits, 1);
	client.clear();
	await client.get("http://x/a");
	await client.get("http://x/b");
	assert.equal(calls, 5);
	const s1 = client.stats();
	s1.hits = 999;
	assert.notDeepEqual(client.stats(), s1); // new object each time
	assert.deepEqual(client.stats(), { hits: 0, misses: 5, fetches: 5 });
	assert.throws(() => client.clear(""), TypeError);
	assert.throws(() => client.clear(42), TypeError);
