// R7: deep copy isolation at depth, incl. shared fetch; url check rejects
{
	let t = 0;
	const client = createClient({
		ttlMs: 1000, now: () => t,
		fetchImpl: async () => ({ status: 200, body: { list: [{ deep: [1, 2] }], s: "x" } }),
	});
	const p1 = client.get("http://x/d");
	const p2 = client.get("http://x/d"); // shares fetch
	const r1 = await p1;
	const r2 = await p2;
	r1.status = 999;
	r1.body.s = "mut";
	r1.body.list[0].deep[0] = 42;
	r2.body.list[0].deep[1] = 43;
	const r3 = await client.get("http://x/d"); // from cache
	assert.deepEqual(r3, { status: 200, body: { list: [{ deep: [1, 2] }], s: "x" } });
	assert.throws(() => client.get(123), { instanceOf: TypeError });
	await assert.rejects(() => client.get(null), TypeError);
	await assert.rejects(() => client.get(""), TypeError);
}

